text={'type':'string','minLength':1,'maxLength':4096};name={'type':'string','pattern':'^[A-Za-z][A-Za-z0-9_]{0,23}$'};num={'type':'number'};cell={'anyOf':[text,num]};fmt={'type':'string','enum':['ascii','latex']}
